CREATE TABLE `dem_klaes_materials` (
                                       `id_` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'идентификатор записи',
                                       `proc` float NOT NULL DEFAULT '0' COMMENT 'процент отхода',
                                       `idorders` int unsigned NOT NULL DEFAULT '0' COMMENT 'id заказа из dem_orders',
                                       `position` smallint unsigned NOT NULL DEFAULT '0' COMMENT 'позиция',
                                       `pole` char(4) CHARACTER SET cp1251 COLLATE cp1251_general_ci NOT NULL COMMENT 'поле',
                                       `field` char(3) CHARACTER SET cp1251 COLLATE cp1251_general_ci DEFAULT NULL COMMENT 'под поле',
                                       `articul_mat` varchar(255) CHARACTER SET cp1251 COLLATE cp1251_general_ci NOT NULL COMMENT 'артикул',
                                       `name_mat` varchar(64) CHARACTER SET cp1251 COLLATE cp1251_general_ci NOT NULL COMMENT 'наименование артикула',
                                       `messure` varchar(5) CHARACTER SET cp1251 COLLATE cp1251_general_ci NOT NULL COMMENT 'в чем измеряется',
                                       `count` float NOT NULL DEFAULT '0' COMMENT 'количество в шт',
                                       `allowances` float NOT NULL DEFAULT '0' COMMENT 'количество в пгм квм кубах и т.д.',
                                       `color` varchar(255) CHARACTER SET cp1251 COLLATE cp1251_general_ci NOT NULL COMMENT 'цвет',
                                       `type` smallint NOT NULL DEFAULT '0' COMMENT 'тип материала',
                                       `price` float NOT NULL DEFAULT '0' COMMENT 'Цена 1 ед материала',
                                       `location` char(1) CHARACTER SET cp1251 COLLATE cp1251_general_ci DEFAULT NULL COMMENT 'расположение',
                                       `width` float NOT NULL DEFAULT '0' COMMENT 'ширина',
                                       `height` float NOT NULL DEFAULT '0' COMMENT 'высота',
                                       `gForm` int NOT NULL DEFAULT '0' COMMENT 'створка',
                                       `nSQ` int NOT NULL DEFAULT '0' COMMENT 'плоскость',
                                       `nRama` int NOT NULL DEFAULT '0' COMMENT 'коробка',
                                       `aUg01` int NOT NULL DEFAULT '0' COMMENT '1 угол запила',
                                       `aUg02` int NOT NULL DEFAULT '0' COMMENT '2 угол запила',
                                       `cLke` int NOT NULL DEFAULT '0',
                                       PRIMARY KEY (`id_`),
                                       KEY `idorders` (`idorders`),
                                       KEY `articul_mat` (`articul_mat`),
                                       KEY `messure` (`messure`),
                                       KEY `type` (`type`),
                                       KEY `color` (`color`),
                                       KEY `position` (`position`),
                                       KEY `pole` (`pole`),
                                       KEY `location` (`location`),
                                       KEY `field` (`field`),
                                       KEY `gForm` (`gForm`,`nSQ`,`nRama`),
                                       KEY `nRama` (`nRama`),
                                       KEY `cLke` (`cLke`)
) ENGINE=MyISAM AUTO_INCREMENT=3638 DEFAULT CHARSET=cp1251 MAX_ROWS=1000000000;








